namespace sv_f23913e0cef24602bf5053a6b27eb6f2.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_f23913e0cef24602bf5053a6b27eb6f2.Components.Pages.Settings

<nav class="settings-nav">
    <h3 class="settings-nav-title">Settings</h3>
    <ul class="settings-nav-list">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="settings-nav-icon">@GetIcon(section)</span>
                <span class="settings-nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_f23913e0cef24602bf5053a6b27eb6f2.Components.Pages.Settings
@using sv_f23913e0cef24602bf5053a6b27eb6f2.Services

<div class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-preview">
        @if (!string.IsNullOrEmpty(AvatarUrl))
        {
            <img src="@AvatarUrl" alt="Avatar" class="avatar-image" />
        }
        else
        {
            <div class="avatar-placeholder">No Avatar</div>
        }
        <p class="avatar-url-display">@AvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="DisplayName" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="Email" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="Bio" class="form-control" rows="4"></textarea>
    </div>

    <div class="form-group">
        <label for="avatarUrl">Avatar URL</label>
        <input id="avatarUrl" type="url" @bind="AvatarUrl" class="form-control" />
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (ShowSuccessMessage)
    {
        <div class="toast-success">Profile saved successfully!</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Bio { get; set; } = "";
    private string AvatarUrl { get; set; } = "";
    private bool ShowSuccessMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        Bio = profile.Bio;
        AvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        ShowSuccessMessage = true;
        _ = HideMessageAfterDelay();
    }

    private async Task HideMessageAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccessMessage = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
    }
}

@namespace sv_f23913e0cef24602bf5053a6b27eb6f2.Components.Pages.Settings
@using sv_f23913e0cef24602bf5053a6b27eb6f2.Services

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="EmailNotifications" />
            <span class="toggle-label">Email Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="PushNotifications" />
            <span class="toggle-label">Push Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="WeeklyDigest" />
            <span class="toggle-label">Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in AvailableChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@IsChannelMuted(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>

    @if (ShowSuccessMessage)
    {
        <div class="toast-success">Notification preferences saved!</div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private bool ShowSuccessMessage { get; set; }

    private static readonly string[] AvailableChannels = ["general", "announcements", "engineering", "design", "marketing", "support"];

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private bool _initialized;

    private bool IsChannelMuted(string channel) => MutedChannels.Contains(channel);

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        ShowSuccessMessage = true;
        _ = HideMessageAfterDelay();
    }

    private async Task HideMessageAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccessMessage = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_f23913e0cef24602bf5053a6b27eb6f2.Components.Pages.Settings

<div class="expandable-panel">
    <button class="panel-header" @onclick="ToggleExpanded">
        <span>Change Password</span>
        <span class="panel-toggle">@(IsExpanded ? "▼" : "▶")</span>
    </button>

    @if (IsExpanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="CurrentPassword" class="form-control" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="NewPassword" class="form-control" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="ConfirmPassword" class="form-control" />
            </div>

            @if (!string.IsNullOrEmpty(ErrorMessage))
            {
                <div class="error-message">@ErrorMessage</div>
            }

            @if (ShowSuccess)
            {
                <div class="toast-success">Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@IsSubmitting">
                @(IsSubmitting ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string? ErrorMessage { get; set; }
    private bool IsSubmitting { get; set; }
    private bool ShowSuccess { get; set; }

    private void ToggleExpanded() => IsExpanded = !IsExpanded;

    private async Task UpdatePasswordAsync()
    {
        ErrorMessage = null;
        ShowSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            ErrorMessage = "Current password is required.";
            return;
        }

        if (string.IsNullOrWhiteSpace(NewPassword))
        {
            ErrorMessage = "New password is required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            ErrorMessage = "New password and confirmation do not match.";
            return;
        }

        IsSubmitting = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            ShowSuccess = true;
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            ErrorMessage = ex.Message;
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

@namespace sv_f23913e0cef24602bf5053a6b27eb6f2.Components.Pages.Settings
@using sv_f23913e0cef24602bf5053a6b27eb6f2.Services

@if (Session is not null)
{
    <div class="dialog-overlay" @onclick="Cancel">
        <div class="dialog-content" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke the session on <strong>@Session.Device</strong> from <strong>@Session.Location</strong>?</p>
            <p class="dialog-subtitle">This will sign out that device immediately.</p>
            <div class="dialog-actions">
                <button class="btn btn-danger" @onclick="Confirm">Revoke</button>
                <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback<string> OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm()
    {
        if (Session is not null)
        {
            await OnConfirm.InvokeAsync(Session.Id);
        }
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@namespace sv_f23913e0cef24602bf5053a6b27eb6f2.Components.Pages.Settings
@using sv_f23913e0cef24602bf5053a6b27eb6f2.Services

<div class="settings-section">
    <h2>Security</h2>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="security-group">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <label class="toggle-item">
                <input type="checkbox" checked="@TwoFactorEnabled" @onchange="ToggleTwoFactor" />
                <span class="toggle-label">Two-Factor Authentication</span>
            </label>
            <span class="status-indicator @(TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
