@namespace sv_f23913e0cef24602bf5053a6b27eb6f2.Components.Pages.Settings
@using sv_f23913e0cef24602bf5053a6b27eb6f2.Services

<div class="settings-section">
    <h2>Security</h2>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="security-group">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <label class="toggle-item">
                <input type="checkbox" checked="@TwoFactorEnabled" @onchange="ToggleTwoFactor" />
                <span class="toggle-label">Two-Factor Authentication</span>
            </label>
            <span class="status-indicator @(TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="last-password-change">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <div class="security-group">
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @if (Settings?.Sessions is not null)
                {
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != Settings.Sessions.FirstOrDefault())
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => ShowRevokeDialog(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-session-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>
    </div>

    <RevokeSessionDialog Session="@_sessionToRevoke"
                         OnConfirm="HandleRevokeConfirmed"
                         OnCancel="HideRevokeDialog" />
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<bool> OnToggleTwoFactor { get; set; }

    private bool TwoFactorEnabled => Settings?.TwoFactorEnabled ?? false;
    private ActiveSession? _sessionToRevoke;

    private async Task HandleChangePassword((string Current, string New) passwords)
    {
        await OnChangePassword.InvokeAsync(passwords);
    }

    private void ShowRevokeDialog(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void HideRevokeDialog()
    {
        _sessionToRevoke = null;
    }

    private async Task HandleRevokeConfirmed(string sessionId)
    {
        _sessionToRevoke = null;
        await OnRevokeSession.InvokeAsync(sessionId);
    }

    private async Task ToggleTwoFactor(ChangeEventArgs e)
    {
        var enabled = (bool)(e.Value ?? false);
        await OnToggleTwoFactor.InvokeAsync(enabled);
    }
}

