.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    width: 250px;
    flex-shrink: 0;
    border-right: 1px solid var(--border-color, #e0e0e0);
    background: var(--sidebar-bg, #f8f9fa);
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

/* Nav */
.settings-nav {
    padding: 1.5rem 0;
}

.settings-nav-title {
    padding: 0 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary, #333);
}

.settings-nav-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
    color: var(--text-secondary, #666);
}

.settings-nav-item:hover {
    background: var(--hover-bg, #e9ecef);
}

.settings-nav-item.active {
    background: var(--active-bg, #e3f2fd);
    border-left-color: var(--primary-color, #1976d2);
    color: var(--primary-color, #1976d2);
    font-weight: 500;
}

.settings-nav-icon {
    font-size: 1.1rem;
}

/* Section */
.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    font-weight: 500;
}

/* Form */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: var(--text-secondary, #555);
}

.form-control {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid var(--border-color, #ccc);
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: var(--primary-color, #1976d2);
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.1);
}

textarea.form-control {
    resize: vertical;
}

/* Buttons */
.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

.btn {
    padding: 0.6rem 1.2rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s, opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: var(--primary-color, #1976d2);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: var(--primary-hover, #1565c0);
}

.btn-secondary {
    background: var(--secondary-bg, #e0e0e0);
    color: var(--text-primary, #333);
}

.btn-secondary:hover:not(:disabled) {
    background: var(--secondary-hover, #d0d0d0);
}

.btn-danger {
    background: #d32f2f;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background: #b71c1c;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: var(--primary-color, #1976d2);
}

.toggle-label {
    font-size: 0.95rem;
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    padding: 0.3rem 0;
}

.channel-item input[type="checkbox"] {
    accent-color: var(--primary-color, #1976d2);
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid var(--border-color, #e0e0e0);
}

.avatar-placeholder {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    background: var(--secondary-bg, #e0e0e0);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto;
    color: var(--text-secondary, #999);
    font-size: 0.85rem;
}

.avatar-url-display {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: var(--text-secondary, #999);
    word-break: break-all;
}

/* Toast */
.toast-success {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    background: #e8f5e9;
    color: #2e7d32;
    border-radius: 6px;
    border: 1px solid #c8e6c9;
    font-size: 0.9rem;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 1.5rem;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 1.25rem;
    background: var(--sidebar-bg, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: var(--hover-bg, #e9ecef);
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid var(--border-color, #e0e0e0);
}

/* Security */
.security-group {
    margin-top: 1.5rem;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.status-indicator {
    padding: 0.25rem 0.6rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 500;
}

.status-enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-disabled {
    background: #fbe9e7;
    color: #d32f2f;
}

.last-password-change {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: var(--text-secondary, #999);
}

.current-session-badge {
    padding: 0.2rem 0.5rem;
    background: #e3f2fd;
    color: var(--primary-color, #1976d2);
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 500;
}

/* Sessions Table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #e0e0e0);
    font-size: 0.9rem;
}

.sessions-table th {
    font-weight: 500;
    color: var(--text-secondary, #666);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

/* Dialog */
.dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog-content {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.dialog-content h3 {
    margin-top: 0;
}

.dialog-subtitle {
    font-size: 0.85rem;
    color: var(--text-secondary, #666);
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    flex-wrap: wrap;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.radio-item input[type="radio"] {
    accent-color: var(--primary-color, #1976d2);
}

/* Live Preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 8px;
    transition: all 0.2s;
}

.live-preview h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

.preview-card {
    margin-top: 0.75rem;
    padding: 0.75rem;
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 6px;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.preview-title {
    font-weight: 600;
}

.preview-body {
    color: var(--text-secondary, #666);
}

/* Preview theme variants */
.preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-card {
    border-color: #444;
}

.preview-theme-dark .preview-body {
    color: #aaa;
}

.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-theme-system {
    background: #f5f5f5;
    color: #333;
}

/* Preview font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact mode */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.4rem;
}

/* Error */
.error-message {
    padding: 0.6rem 0.8rem;
    background: #fbe9e7;
    color: #d32f2f;
    border-radius: 6px;
    margin-bottom: 0.75rem;
    font-size: 0.85rem;
}

/* Loading */
.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    color: var(--text-secondary, #999);
    font-size: 1rem;
}

