toolArgs.file_text:
.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    width: 250px;
    flex-shrink: 0;
    border-right: 1px solid var(--border-color, #e0e0e0);
    background: var(--sidebar-bg, #f8f9fa);
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

/* Nav */
.settings-nav {
    padding: 1.5rem 0;
}

.settings-nav-title {
    padding: 0 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary, #333);
}

.settings-nav-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
    color: var(--text-secondary, #666);
}

.settings-nav-item:hover {
    background: var(--hover-bg, #e9ecef);
}

.settings-nav-item.active {
    background: var(--active-bg, #e3f2fd);
    border-left-color: var(--primary-color, #1976d2);
    color: var(--primary-color, #1976d2);
    font-weight: 500;
}

.settings-nav-icon {
    font-size: 1.1rem;
}

/* Section */
.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    font-weight: 500;
}

/* Form */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: var(--text-secondary, #555);
}

.form-control {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid var(--border-color, #ccc);
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: var(--primary-color, #1976d2);
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.1);
}

textarea.form-control {
    resize: vertical;
}

/* Buttons */
.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

.btn {
    padding: 0.6rem 1.2rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s, opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: var(--primary-color, #1976d2);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: var(--primary-hover, #1565c0);
}

.btn-secondary {
    background: var(--secondary-bg, #e0e0e0);
    color: var(--text-primary, #333);
}

.btn-secondary:hover:not(:disabled) {
    background: var(--secondary-hover, #d0d0d0);
}

.btn-danger {
    background: #d32f2f;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background: #b71c1c;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
